<script setup>
import { computed,onMounted,onBeforeUnmount,reactive,ref,watch } from 'vue';
import {registerPosBackLayer} from '../../shared/pos-back-navigation.js';
import DeviceSession from '../sales/DeviceSession.vue';
import { salePayload,money,providerNames,stateNames,canReceipt,errorText } from './digital-model.js';
import {topupUnavailableReason} from '../finance/topup-funding.js';
import {usePreferencesTranslator} from '../preferences/preferences-state.js';
const props=defineProps({vm:{type:Object,required:true},focusedOffer:{type:Object,default:null},deviceSession:{type:Boolean,default:true}}),emit=defineEmits(['issued','back']);
const form=reactive({connection_id:'',offer_id:'',mobile:'',confirm_mobile:'',first_name:'',last_name:'',bein_province_id:''}),confirmation=ref(null),pending=ref(null),order=ref(null),recovering=ref(true);
const quotedOffer=ref(null),quoteLoading=ref(false);
const uiLabel=usePreferencesTranslator();
async function recover(){recovering.value=true;try{const response=await props.vm.api.recovery(props.vm.signal);order.value=response.data.order;pending.value=null;confirmation.value=null;recovering.value=false;}catch(error){props.vm.state.error=await props.vm.failure(error);}}
onMounted(recover);
let releaseBack;
onMounted(()=>{releaseBack=registerPosBackLayer({state:digitalBackState,back:digitalBack});});
onBeforeUnmount(()=>releaseBack?.());
async function newSale(){if(props.vm.state.busy||!order.value||order.value.reservation_active)return;props.vm.state.busy=true;try{await props.vm.api.acknowledge(order.value.id,props.vm.signal);order.value=null;reset();}catch(error){props.vm.state.error=await props.vm.failure(error);}finally{props.vm.state.busy=false;}}
const connections=computed(()=>props.vm.state.connections.filter(row=>props.vm.state.offers.some(offer=>offer.connection_id===row.id))),offers=computed(()=>props.vm.state.offers.filter(row=>Number(row.connection_id)===Number(form.connection_id))),selected=computed(()=>quotedOffer.value||props.focusedOffer||offers.value.find(row=>Number(row.id)===Number(form.offer_id)));
const fundingReason=computed(()=>topupUnavailableReason(selected.value));
const needsPhone=computed(()=>selected.value?.provider==='topup'||selected.value?.package_type==='premium');
watch(()=>props.focusedOffer,offer=>{quotedOffer.value=null;if(offer){form.connection_id=offer.connection_id;form.offer_id=offer.id;}},{immediate:true});
watch(()=>[form.connection_id,form.offer_id],()=>{quotedOffer.value=null;confirmation.value=null;});
async function preview(){
 if(props.vm.state.busy||quoteLoading.value||recovering.value||pending.value||order.value||confirmation.value)return;
 props.vm.state.error='';quoteLoading.value=true;
 try{
  let offer=selected.value;salePayload(offer,form);
  if(offer.provider==='topup'){
   const response=await props.vm.api.offers(props.vm.signal,{fresh:true});
   const fresh=response.data.find(row=>Number(row.id)===Number(offer.id)&&Number(row.connection_id)===Number(offer.connection_id));
   if(!fresh)throw Error('هذه الفئة غير متاحة للبيع حاليًا.');
   if(Number(form.offer_id)!==Number(offer.id)||Number(form.connection_id)!==Number(offer.connection_id))return;
   quotedOffer.value=fresh;offer=fresh;
   const reason=topupUnavailableReason(offer);if(reason)throw Error(reason);
  }
  confirmation.value=salePayload(offer,form);
 }catch(error){confirmation.value=null;props.vm.state.error=await props.vm.failure(error);}finally{quoteLoading.value=false;}
}
async function submit(){if(props.vm.state.busy||quoteLoading.value||recovering.value||order.value||(!pending.value&&!confirmation.value))return;const payload=pending.value||{...confirmation.value,request_id:crypto.randomUUID()};pending.value=Object.freeze(payload);props.vm.state.busy=true;props.vm.state.error='';try{const response=await props.vm.api.create(payload,props.vm.signal);order.value=response.data;pending.value=null;confirmation.value=null;emit('issued',order.value);if(canReceipt(order.value,props.vm.identity.value,props.vm.can))await props.vm.openReceipt(order.value);}catch(error){props.vm.state.error=await props.vm.failure(error);await recover();}finally{props.vm.state.busy=false;}}
function reset(){if(pending.value)return;order.value=null;confirmation.value=null;Object.assign(form,{mobile:'',confirm_mobile:'',first_name:'',last_name:'',bein_province_id:''});emit('back');}
function digitalBackState(){return !props.vm.pos.value?'none':props.vm.state.busy||quoteLoading.value||recovering.value||pending.value||order.value?.reservation_active?'blocked':confirmation.value||props.focusedOffer?'open':'none';}
function digitalBack(){if(confirmation.value)confirmation.value=null;else reset();}
</script>
<template><div><DeviceSession v-if="deviceSession" :vm="vm"/><section v-if="!vm.receipt.value" class="card"><div v-if="focusedOffer" class="pos-phone-title"><h3>{{focusedOffer.name}}</h3><button class="btn small" :disabled="vm.state.busy||quoteLoading||!!pending" @click="reset">رجوع</button></div><p v-if="recovering" class="notice">جارٍ التحقق من آخر عملية… <button type="button" class="btn small" @click="recover">تحديث</button></p><section v-if="order" class="digital-confirm"><h3>آخر عملية</h3><p>{{order.product_name}} · {{money(order.retail)}} د.ع</p><p class="mono">{{order.mobile}} · {{order.company_transaction_id||order.request_id}}</p><p>{{stateNames[order.status]}} · {{order.message}}</p><div class="actions"><button v-if="canReceipt(order,vm.identity.value,vm.can)" class="btn" @click="vm.openReceipt(order)">الإيصال</button><button v-if="order.reservation_active" class="btn" :disabled="vm.state.busy" @click="recover">تحديث النتيجة</button><button v-else class="btn primary" :disabled="vm.state.busy" @click="newSale">اطلعت على النتيجة · بدء بيع جديد</button></div></section><form v-if="!recovering&&!order" @submit.prevent="preview"><div class="formgrid"><label v-if="!focusedOffer">الخدمة والوكيل<select v-model="form.connection_id" required :disabled="vm.state.busy||quoteLoading||!!pending||!!confirmation"><option value="" disabled>اختر الخدمة</option><option v-for="row in connections" :key="row.id" :value="row.id">{{providerNames[row.provider]}} · {{row.account_name}}</option></select></label><label v-if="!focusedOffer">الفئة<select v-model="form.offer_id" required :disabled="vm.state.busy||quoteLoading||!!pending||!!confirmation"><option value="" disabled>اختر الفئة</option><option v-for="row in offers" :key="row.id" :value="row.id">{{row.name}} · {{money(row.retail)}} د.ع</option></select></label><label v-if="needsPhone">رقم الزبون<input v-model="form.mobile" type="tel" dir="ltr" placeholder="07701234567" required :disabled="vm.state.busy||quoteLoading||!!pending||!!confirmation"></label><label v-if="needsPhone">تأكيد رقم الزبون<input v-model="form.confirm_mobile" type="tel" dir="ltr" required :disabled="vm.state.busy||quoteLoading||!!pending||!!confirmation"></label><template v-if="selected?.package_type==='premium'"><label>اسم المشترك<input v-model="form.first_name" required maxlength="100" :disabled="vm.state.busy||quoteLoading||!!pending||!!confirmation"></label><label>محافظة المشترك<select v-model="form.bein_province_id" required :disabled="vm.state.busy||quoteLoading||!!pending||!!confirmation"><option value="" disabled>اختر المحافظة</option><option v-for="row in selected.bein_provinces" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>اسم العائلة<input v-model="form.last_name" required maxlength="100" :disabled="vm.state.busy||quoteLoading||!!pending||!!confirmation"></label></template></div><div v-if="selected" class="digital-sale-summary"><span>مبلغ البيع</span><strong>{{money(selected.retail)}} د.ع</strong></div><div v-if="selected?.provider==='topup'" class="digital-sale-summary" data-topup-wallet><span>رصيدك المتاح في Topup</span><strong>{{money(selected.wallet_available)}} د.ع</strong></div><p v-if="fundingReason" class="notice warn" role="status">{{uiLabel(fundingReason)}}</p><p v-if="selected&&!selected.gateway.configured" class="notice warn">الخدمة غير متصلة: {{selected.gateway.missing.join('، ')}}.</p><p v-else-if="selected&&!selected.gateway.purchases_enabled" class="notice warn">تنفيذ المشتريات الخارجية غير مفعّل بعد اعتماد الربط الفعلي.</p><div class="formfoot"><button class="btn primary" :disabled="vm.state.busy||quoteLoading||!selected||!!pending||!!fundingReason||!selected.gateway.configured||!selected.gateway.purchases_enabled">{{quoteLoading?'جارٍ التحقق من رصيد Topup…':'مراجعة العملية'}}</button></div></form><section v-if="confirmation||pending" class="digital-confirm" role="region" aria-label="تأكيد العملية"><h3>تأكيد العملية</h3><p>{{vm.identity.value?.account.name}} · {{selected?.name}} · {{money((pending||confirmation).expected_retail)}} د.ع</p><p v-if="(pending||confirmation).mobile" class="mono">{{(pending||confirmation).mobile}}</p><p v-if="pending" class="notice warn">النتيجة غير مؤكدة. إعادة المحاولة هنا تستخدم مرجع الطلب نفسه؛ راجع السجل قبل أي شراء جديد.</p><div class="actions"><button class="btn primary" :disabled="vm.state.busy" @click="submit">{{vm.state.busy?'جارٍ التنفيذ…':pending?'استعلام عن نفس الطلب':'تأكيد البيع'}}</button><button v-if="!pending" class="btn" :disabled="vm.state.busy" @click="confirmation=null">رجوع</button></div></section><p v-if="order" class="notice" :class="{warn:order.reservation_active}">{{stateNames[order.status]}} · {{order.message}}</p><p v-if="!connections.length&&!focusedOffer" class="empty">لا توجد خدمة مفعّلة لهذه النقطة؛ راجع الوكيل.</p></section></div></template>
